    return ho_fused_post_expert_norm_weighted_sum(y.view(bs, ho_TOP_K, bank.d_hidden), topk_weights, norm_weight=state['norm_w'], eps=ho_POST_NORM_EPS, weight_first=True, slot_expert_ids=local_ids)

